prompt --application/shared_components/logic/application_processes/arf_lite_prepare_url
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(218432492932118160)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'ARF_LITE_PREPARE_URL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   l_report_name  VARCHAR2(255);',
'   l_output_name  VARCHAR2(255);',
'   l_report_param VARCHAR2(2000);',
'   l_url          VARCHAR2(4000);',
'   l_session      NUMBER := v(''APP_SESSION'');',
'   l_app_id       NUMBER := v(''APP_ID'');',
'   l_report_mode VARCHAR2(1);',
'BEGIN',
'   l_report_name  := apex_application.g_x01;',
'   l_report_param := apex_application.g_x02;',
'   l_output_name := apex_application.g_x03;',
'   l_report_mode := nvl(apex_application.g_x04,''P'');',
'',
'   l_url          := apex_util.prepare_url(',
'      p_url           => ''f?p=''',
'               || l_app_id',
'               || '':0:''',
'               || l_session',
'               || '':APPLICATION_PROCESS=ARF_LITE_REPORT_DOWNLOAD:::ARF_LITE_REPORT_NAME,ARF_LITE_REPORT_PARAM,ARF_LITE_DOWNLOAD_NAME,ARF_LITE_REPORT_MODE:''',
'               || l_report_name',
'               || '',''',
'               || l_report_param',
'               || '',''',
'               || l_output_name',
'               || '',''',
'               || l_report_mode',
'               || '':''',
'    , p_checksum_type => ''SESSION''',
'   );',
'',
'   htp.p(apex_util.host_url || l_url);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_version_scn=>39538117549457
);
end;
/
prompt --application/shared_components/logic/application_processes/arf_lite_report_download
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(218432705402119360)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'ARF_LITE_REPORT_DOWNLOAD'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   l_file         BLOB;',
'   l_filename     VARCHAR2(255) := nvl(',
'      :arf_lite_download_name',
'    , to_char(TO_NUMBER(sys_guid()',
'              , ''XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX''))',
'   );',
'   l_content_type VARCHAR2(255);',
'   l_render_mode  VARCHAR2(255) := nvl(',
'      :arf_lite_report_mode',
'    , ''P''',
'   );',
'BEGIN',
'   FOR i IN (',
'      SELECT',
'         d.output_format',
'       , d.main_report_name',
'       , (',
'            CASE d.output_format',
'                WHEN ''PDF''   THEN ''application/pdf''',
'                WHEN ''EXCEL'' THEN ''application/vnd.openxmlformats-officedocument.spreadsheetml.sheet''',
'                WHEN ''DOCX''  THEN ''application/vnd.openxmlformats-officedocument.wordprocessingml.document''',
'                WHEN ''PPTX''  THEN ''application/vnd.openxmlformats-officedocument.presentationml.presentation''  -- NEW',
'                WHEN ''HTML''  THEN ''text/html''',
'                WHEN ''ODT''   THEN ''application/vnd.oasis.opendocument.text''   -- NEW',
'                WHEN ''RTF''   THEN ''application/rtf''                            -- NEW',
'                WHEN ''TXT''   THEN ''text/plain''                                -- NEW',
'                WHEN ''XML''   THEN ''application/xml''',
'                WHEN ''CSV''   THEN ''text/csv''',
'                ELSE ''application/octet-stream''',
'        END',
'         ) mime_type',
'       , (',
'            CASE d.output_format',
'                WHEN ''PDF''   THEN ''.pdf''',
'                WHEN ''EXCEL'' THEN ''.xlsx''',
'                WHEN ''DOCX''  THEN ''.docx''',
'                WHEN ''PPTX''  THEN ''.pptx''   -- NEW',
'                WHEN ''HTML''  THEN ''.html''',
'                WHEN ''ODT''   THEN ''.odt''    -- NEW',
'                WHEN ''RTF''   THEN ''.rtf''    -- NEW',
'                WHEN ''TXT''   THEN ''.txt''    -- NEW',
'                WHEN ''XML''   THEN ''.xml''',
'                WHEN ''CSV''   THEN ''.csv''',
'                ELSE ''.bin''',
'             END',
'         ) file_extension',
'      FROM',
'         arf_lite_report_definition d',
'      WHERE',
'         d.short_code = utl_url.unescape(:arf_lite_report_name)',
'   ) LOOP',
'      SELECT',
'         arf_lite_util.get_report(',
'            p_report_code  => utl_url.unescape(:arf_lite_report_name)',
'          , p_report_param => utl_url.unescape(:arf_lite_report_param)',
'         ) blob_content',
'      INTO l_file',
'      FROM',
'         dual;',
'',
'      l_filename := l_filename || i.file_extension;',
'      IF',
'         l_render_mode = ''P''',
'         AND i.mime_type IN ( ''application/pdf''',
'                            , ''text/html''',
'                            , ''application/xml'' )',
'      THEN',
'         owa_util.mime_header(',
'            i.mime_type',
'          , FALSE',
'         );',
'         htp.p(''Content-Length: '' || dbms_lob.getlength(l_file));',
'         owa_util.http_header_close;',
'         wpg_docload.download_file(l_file);',
'      ELSE',
'         apex_http.download(',
'            p_blob         => l_file',
'          , p_content_type => i.mime_type',
'          , p_filename     => l_filename',
'         );',
'      END IF;',
'',
'   END LOOP;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_version_scn=>47006818252610
);
end;
/
prompt --application/shared_components/logic/application_processes/mtcarf_prepare_params
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(243419650756825359)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'MTCARF_PREPARE_PARAMS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   l_base_url       mtc_arf_config.base_url%TYPE;',
'   l_client_id      mtc_arf_config.client_id%TYPE;',
'   l_client_secret  mtc_arf_config.client_secret%TYPE;',
'   l_org_id         mtc_arf_config.org_id%TYPE;',
'   l_token          VARCHAR2(2000);',
'   l_user_id        VARCHAR2(256);',
'BEGIN',
'   SELECT',
'      base_url',
'    , client_id',
'    , client_secret',
'    , :app_user',
'    , org_id',
'   INTO',
'      l_base_url',
'   , l_client_id',
'   , l_client_secret',
'   , l_user_id',
'   , l_org_id',
'   FROM',
'      mtc_arf_config org;',
'',
'   l_token := mtc_rpf_utilities_pkg.encode_jwt(',
'                                              p_userid => l_user_id',
'                                            , p_orgid => l_org_id',
'                                            , p_client_id => l_client_id',
'                                            , p_client_secret => l_client_secret',
'              );',
'',
'   apex_json.open_object;',
'   apex_json.open_array(''params'');',
'   apex_json.open_object;',
'   apex_json.write(',
'                  ''orgId''',
'                , l_org_id',
'   );',
'   apex_json.write(',
'                  ''userId''',
'                , l_user_id',
'   );',
'   apex_json.write(',
'                  ''token''',
'                , l_token',
'   );',
'   apex_json.write(',
'                  ''baseUrl''',
'                , l_base_url',
'   );',
'   apex_json.close_object;',
'   apex_json.close_array;',
'   apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_version_scn=>21383263
);
end;
/
