wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(242864225781766398)
,p_plug_name=>'Search Results'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'   "ORDER_ID"',
' , to_char(',
'      order_date',
'    , ''DD-MON-YYYY''',
'   ) order_date',
' , decode(',
'      order_mode',
'    , ''online''',
'    , ''Online''',
'    , ''direct''',
'    , ''Direct''',
'   ) order_mode',
' , "CUSTOMER_ID"',
' , (',
'      SELECT',
'         ''#'' || m.ORDER_ID ||'' ''|| l1."CUST_FIRST_NAME"',
'      FROM',
'         "OEHR_CUSTOMERS" l1',
'      WHERE',
'         l1."CUSTOMER_ID" = m."CUSTOMER_ID"',
'   ) "CUSTOMER_ID_L$1"',
' , (',
'      SELECT',
'         "CUST_FIRST_NAME"',
'      FROM',
'         "OEHR_CUSTOMERS" l1',
'      WHERE',
'         l1."CUSTOMER_ID" = m."CUSTOMER_ID"',
'   ) CUST_FIRST_NAME',
' , "ORDER_STATUS"',
' , to_char(',
'      order_total',
'    , ''999G999G999G999G990D00''',
'   ) order_total_disp',
'   , order_total',
' , "SALES_REP_ID"',
' , (',
'      SELECT',
'         l2."FIRST_NAME"',
'      FROM',
'         "OEHR_EMPLOYEES" l2',
'      WHERE',
'         l2."EMPLOYEE_ID" = m."SALES_REP_ID"',
'   ) "SALES_REP_ID_L$2"',
' , "PROMOTION_ID"',
' , (',
'      CASE',
'         WHEN m.order_mode = ''online'' THEN',
'            ''online-order''',
'         WHEN m.order_mode = ''direct'' THEN',
'            ''direct-order''',
'      END',
'   ) badge_css',
'FROM',
'   "OEHR_ORDERS" m'))
,p_query_order_by_type=>'ITEM'
,p_query_order_by=>'{ "itemName": "P5_ORDER_BY", "orderBys": [{"key":"CUSTOMER_ID_L$1","expr":"\"CUSTOMER_ID_L$1\" asc"},{"key":"ORDER_DATE","expr":"\"ORDER_DATE\" asc"},{"key":"ORDER_MODE","expr":"\"ORDER_MODE\" asc"}]}'
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
