,p_event_result=>'TRUE'
,p_action_sequence=>30
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function() {',
'    var reportName = ''EMPLOYEES_ID_CARD''; ',
'    var reportParam = ''[{"parameter_name": "p_from_emp_id","parameter_value": "'' + apex.item(''P8_FROM_EMP_ID'').getValue() + ''"}, {"parameter_name": "p_to_emp_id","parameter_value": "'' + apex.item(''P8_TO_EMP_ID'').getValue() + ''"}]'';',
'    var outputName = ''employees-id-card'';',
'    var renderMode = ''P'';',
'    console.log(reportParam);',
'    var encodedReportParam = encodeURIComponent(reportParam);',
