,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'   emp.employee_id',
' , emp.email',
' , emp.phone_number',
' , emp.hire_date',
' , emp.salary',
' , emp.commission_pct',
' , dept.department_name',
' , emp.department_id',
' , emp.first_name',
'     || '' ''',
'     || emp.last_name  name',
' , job.job_title',
' , mng.first_name',
'     || '' ''',
'     || mng.last_name  manager_name',
' , loc.street_address',
'     || '', ''',
'     || loc.city',
'     || '', ''',
'     || loc.country_id location',
'FROM',
'   oehr_employees   emp',
' , oehr_departments dept',
' , oehr_jobs        job',
' , oehr_employees   mng',
' , oehr_locations   loc',
'WHERE',
'      emp.department_id = dept.department_id',
'   AND emp.job_id (+)      = job.job_id',
'   AND mng.employee_id (+) = dept.manager_id',
'   AND loc.location_id     = dept.location_id'))
,p_is_editable=>false
,p_plug_source_type=>'NATIVE_FORM'
);
