wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(218408113204040248)
,p_event_id=>wwv_flow_imp.id(218407585137040247)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'l_data clob;',
'l_key            RAW(32);       -- AES256 requires 32-byte key',
'l_iv             RAW(16);       -- AES block size = 128 bits (16 bytes)',
'begin',
'for i in(',
'SELECT',
'            c.base_url || ''/export'' base_url',
'          , c.api_key',
'          , nvl(:P28_TEST_ENCRYPT,''N'')                      encryption_enabled',
'          , c.encryption_key',
'          , c.encryption_iv',
'          , d.output_format',
'          , d.main_report_name',
'         FROM',
'            arf_lite_config            c',
'          , arf_lite_report_definition d',
'         WHERE',
'            d.short_code = utl_url.unescape(:P28_SHORT_CODE)',
'      ) LOOP',
'         l_data        := arf_lite_util.get_data(',
'            p_report_code  => :P28_SHORT_CODE',
'          , p_report_param => :P28_TEST_PARAM',
'         );',
'         IF i.encryption_enabled = ''Y'' THEN',
'            l_key  := hextoraw(i.encryption_key);',
'            l_iv   := hextoraw(i.encryption_iv);',
'            l_data := arf_lite_util.encrypt_clob_aes(',
'               p_clob => l_data',
'             , p_key  => l_key',
'             , p_iv   => l_iv',
'            );',
'         END IF; -- result encryption required',
'end loop;',
':P28_TEST_DATA := l_data;',
'end;',
''))
,p_attribute_02=>'P28_TEST_PARAM,P28_SHORT_CODE,P28_TEST_ENCRYPT'
,p_attribute_03=>'P28_TEST_DATA'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
