prompt --application/deployment/install/install_install
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(221184212791353457)
,p_install_id=>wwv_flow_imp.id(218305616005660395)
,p_name=>'install'
,p_sequence=>10
,p_script_type=>'INSTALL'
,p_condition_type=>'NOT_EXISTS'
,p_condition=>'select  1 from USER_OBJECTS  where object_name = ''ARF_LITE_SCHEMA_LOG'' and object_type = ''TABLE'';'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'CREATE TABLE "ARF_LITE_SCHEMA_LOG" ',
'(	"ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 42493 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, ',
'"UPDATED_ON" TIMESTAMP (6), ',
'"APP_VERSION" VARCHAR2(30 CHAR), ',
'"VERSION_SEQ" NUMBER',
') NO INMEMORY ;',
'/',
'',
'merge INTO ARF_LITE_SCHEMA_LOG msl USING',
'( SELECT ''25.03.00'' app_version, 250300 version_seq FROM dual',
') x ON ( msl.app_version = x.app_version AND msl.version_seq = x.version_seq )',
'WHEN NOT matched THEN',
'  INSERT',
'    (',
'      updated_on',
'    , app_version',
'    , version_seq',
'    )',
'    VALUES',
'    (',
'      systimestamp',
'    , x.app_version',
'    , x.version_seq',
'    );',
'/',
'',
'  CREATE TABLE "ARF_LITE_CONFIG" ',
'   (	"ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, ',
'	"BASE_URL" VARCHAR2(2000 CHAR), ',
'	"API_KEY" VARCHAR2(256 CHAR), ',
'	"ENCRYPTION_ENABLED" VARCHAR2(1 CHAR) DEFAULT ON NULL ''N'' NOT NULL ENABLE, ',
'	"ENCRYPTION_KEY" VARCHAR2(256 CHAR), ',
'	"ENCRYPTION_IV" VARCHAR2(256 CHAR), ',
'	"CREATED_BY" VARCHAR2(256 CHAR), ',
'	"CREATED_ON" TIMESTAMP (6), ',
'	"UPDATED_BY" VARCHAR2(256 CHAR), ',
'	"UPDATED_ON" TIMESTAMP (6), ',
'	 CONSTRAINT "ARF_LITE_CONFIG_ID_PK" PRIMARY KEY ("ID")',
'  USING INDEX  ENABLE',
'   ) ;',
'/',
'',
'  CREATE TABLE "ARF_LITE_REPORT_DEFINITION" ',
'   (	"ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, ',
'	"SHORT_CODE" VARCHAR2(30 CHAR), ',
'	"REPORT_QUERY" CLOB, ',
'	"DESCRIPTION" VARCHAR2(256 CHAR), ',
'	"ACTIVE" VARCHAR2(1 CHAR) DEFAULT ON NULL ''N'' NOT NULL ENABLE, ',
'	"CREATED_BY" VARCHAR2(256 CHAR), ',
'	"CREATED_ON" TIMESTAMP (6), ',
'	"UPDATED_BY" VARCHAR2(256 CHAR), ',
'	"UPDATED_ON" TIMESTAMP (6), ',
'	"OUTPUT_FORMAT" VARCHAR2(30), ',
'	"MAIN_REPORT_NAME" VARCHAR2(200), ',
'    "REPORT_PARAM" VARCHAR2(2048),',
'	 CONSTRAINT "ARF_LITE_REPORT_DEFINITION_ID_PK" PRIMARY KEY ("ID")',
'  USING INDEX  ENABLE',
'   ) ;',
'/',
'',
'CREATE UNIQUE INDEX "ARF_LITE_SCHEMA_LOG_ID_PK" ON "ARF_LITE_SCHEMA_LOG" ("ID") ;',
'ALTER TABLE "ARF_LITE_SCHEMA_LOG" ADD CONSTRAINT "ARF_LITE_SCHEMA_LOG_ID_PK" PRIMARY KEY ("ID")',
'  USING INDEX "ARF_LITE_SCHEMA_LOG_ID_PK"  ENABLE;',
'COMMENT ON COLUMN "ARF_LITE_SCHEMA_LOG"."ID" IS ''Primary key'';',
'COMMENT ON COLUMN "ARF_LITE_SCHEMA_LOG"."UPDATED_ON" IS ''Standard who column. Updated date with time.'';',
'COMMENT ON COLUMN "ARF_LITE_SCHEMA_LOG"."APP_VERSION" IS ''Application version'';',
'COMMENT ON COLUMN "ARF_LITE_SCHEMA_LOG"."VERSION_SEQ" IS ''Application version sequence'';',
'COMMENT ON TABLE "ARF_LITE_SCHEMA_LOG"  IS ''The table to store application schema logs'';',
'/',
'',
'create or replace package "ARF_LITE_UTIL" as',
'',
'function get_data(',
'	p_report_code  varchar2,',
'	p_report_param varchar2 default ''[]''',
') return clob;',
'function get_report(',
'	p_report_code  varchar2,',
'	p_report_param varchar2 default ''[]''',
') return blob;',
'function encrypt_clob_aes (',
'    p_clob IN CLOB,',
'    p_key  IN RAW, -- RAW(32) for 256-bit key',
'    p_iv   IN RAW  -- RAW(16) for 16-byte IV',
') RETURN CLOB;',
'end "ARF_LITE_UTIL";',
'/',
'',
'',
'create or replace PACKAGE BODY "ARF_LITE_UTIL" AS',
'',
'   FUNCTION get_data (',
'      p_report_code  VARCHAR2',
'    , p_report_param VARCHAR2 DEFAULT ''[]''',
'   ) RETURN CLOB AS',
'      l_response CLOB;',
'      l_sql      CLOB;',
'',
'    /* Paremeter Example',
'    [{"parameter_name": "po_id","parameter_value": "41827"}]',
'    Parameter name is case sensitive and it is a json array. The data type conversion to be handled in the query.',
'    [',
'      {',
'        "parameter_name": "Parameter 1",',
'        "parameter_value": "Value 1"',
'      },',
'      {',
'        "parameter_name": "Parameter 2",',
'        "parameter_value": "Value 2"',
'      },',
'      {',
'        "parameter_name": "Parameter 3",',
'        "parameter_value": "Value 3"',
'      }',
'    ]',
'   */',
'   BEGIN',
'      SELECT',
'         report_query',
'      INTO l_sql',
'      FROM',
'         arf_lite_report_definition',
'      WHERE',
'            short_code = utl_url.unescape(p_report_code)',
'         AND active = ''Y'';',
'',
'  -- Apply parameters',
'',
'      FOR i IN (',
'         WITH param_base AS (',
'            SELECT',
'               p_report_param AS json_data',
'            FROM',
'               dual',
'         )',
'         SELECT',
'            jt.parameter_name',
'          , jt.parameter_value',
'         FROM',
'            param_base',
'            CROSS APPLY',
'               JSON_TABLE ( param_base.json_data, ''$[*]''',
'                  COLUMNS (',
'                     parameter_name VARCHAR2 ( 64 ) PATH ''$.parameter_name''',
'                  , parameter_value VARCHAR2 ( 4000 ) PATH ''$.parameter_value''',
'                  )',
'               )',
'            jt',
'      ) LOOP',
'         l_sql := replace(',
'            l_sql',
'          , ''$p{''',
'            || i.parameter_name',
'            || ''}''',
'          , i.parameter_value',
'         );',
'      END LOOP;',
'',
'      EXECUTE IMMEDIATE l_sql',
'      INTO l_response;',
'      l_response := ''{"data": ''',
'                    || l_response',
'                    || ''}'';',
'      RETURN l_response;',
'   EXCEPTION',
'      WHEN OTHERS THEN',
'         dbms_output.put_line(sqlerrm);',
'         raise_application_error(',
'            -20001',
'          , ''An error was encountered - ''',
'            || to_char(sqlcode)',
'            || '' -ERROR- ''',
'            || sqlerrm',
'         );',
'',
'   END get_data;',
'',
'   FUNCTION get_report (',
'      p_report_code  VARCHAR2',
'    , p_report_param VARCHAR2 DEFAULT ''[]''',
'   ) RETURN BLOB AS',
'',
'      l_data           CLOB;',
'      l_request_url    VARCHAR2(2000);',
'      l_response       BLOB;',
'      l_key            RAW(32);       -- AES256 requires 32-byte key',
'      l_iv             RAW(16);       -- AES block size = 128 bits (16 bytes)',
'      l_crypto_type    PLS_INTEGER := dbms_crypto.encrypt_aes256 + dbms_crypto.chain_cbc + dbms_crypto.pad_pkcs5;',
'   BEGIN',
'      FOR i IN (',
'         SELECT',
'            c.base_url || ''/export'' base_url',
'          , c.api_key',
'          , nvl(',
'               c.encryption_enabled',
'             , ''N''',
'            )                       encryption_enabled',
'          , c.encryption_key',
'          , c.encryption_iv',
'          , d.output_format',
'          , d.main_report_name',
'         FROM',
'            arf_lite_config            c',
'          , arf_lite_report_definition d',
'         WHERE',
'            d.short_code = utl_url.unescape(p_report_code)',
'      ) LOOP',
'         l_data        := arf_lite_util.get_data(',
'            p_report_code  => p_report_code',
'          , p_report_param => p_report_param',
'         );',
'         IF i.encryption_enabled = ''Y'' THEN',
'            l_key  := hextoraw(i.encryption_key);',
'            l_iv   := hextoraw(i.encryption_iv);',
'            l_data := arf_lite_util.encrypt_clob_aes(',
'               p_clob => l_data',
'             , p_key  => l_key',
'             , p_iv   => l_iv',
'            );',
'',
'            -- dbms_output.put_line(l_data);',
'         END IF; -- result encryption required',
'',
'         l_request_url := i.base_url;',
'',
'    -- Set the request headers',
'         apex_web_service.set_request_headers(',
'            p_name_01  => ''Content-Type''',
'          , p_value_01 => ''application/json''',
'          , p_name_02  => ''X-API-KEY''',
'          , p_value_02 => i.api_key',
'          , p_name_03  => ''reportFormat''',
'          , p_value_03 => i.output_format',
'          , p_name_04  => ''reportTemplateMain''',
'          , p_value_04 => i.main_report_name',
'         );',
'',
'      -- Call the web service',
'         l_response    := apex_web_service.make_rest_request_b(',
'            p_url         => l_request_url',
'          , p_http_method => ''POST''',
'          , p_body        => l_data',
'         );',
'',
'         IF apex_web_service.g_status_code != 200 THEN',
'            dbms_output.put_line(''error in genering report.'' || apex_web_service.g_status_code);',
'         END IF; -- Status code check',
'      END LOOP;',
'',
'      RETURN l_response;',
'   END get_report;',
'',
'   FUNCTION encrypt_clob_aes (',
'      p_clob IN CLOB',
'    , p_key  IN RAW',
'    , p_iv   IN RAW',
'   ) RETURN CLOB AS',
'',
'      l_encrypted_blob BLOB;',
'      l_decrypted_clob CLOB;',
'      l_key            RAW(32);',
'      l_iv             RAW(16);',
'      l_crypto_type    PLS_INTEGER := dbms_crypto.encrypt_aes256 + dbms_crypto.chain_cbc + dbms_crypto.pad_pkcs5;',
'      l_blob_length    PLS_INTEGER;',
'      l_encrypted_hex  CLOB;',
'      l_offset         PLS_INTEGER := 1;',
'      l_chunk_size     PLS_INTEGER := 16383; -- Max is half of 32767 for RAWTOHEX expansion',
'      l_raw_chunk      RAW(16383);  -- Half of 32767 due to RAWTOHEX doubling size',
'      l_hex_chunk      VARCHAR2(32767);',
'      l_amount         PLS_INTEGER;',
'   BEGIN',
'',
'   -- Generate random encryption key and IV',
'      l_key         := p_key; -- DBMS_CRYPTO.RANDOMBYTES(32);',
'      l_iv          := p_iv; -- DBMS_CRYPTO.RANDOMBYTES(16);',
'',
'   -- Initialize LOBs',
'      dbms_lob.createtemporary(',
'         l_encrypted_blob',
'       , TRUE',
'      );',
'',
'   -- Encrypt CLOB to BLOB',
'      dbms_crypto.encrypt(',
'         dst => l_encrypted_blob',
'       , src => p_clob',
'       , typ => l_crypto_type',
'       , key => l_key',
'       , iv  => l_iv',
'      );',
'',
' -- Convert encrypted BLOB to CLOB',
'',
'      l_blob_length := dbms_lob.getlength(l_encrypted_blob);',
'',
'  -- Initialize the l_encrypted_hex CLOB',
'      dbms_lob.createtemporary(',
'         l_encrypted_hex',
'       , TRUE',
'      );',
'      dbms_lob.open(',
'         l_encrypted_hex',
'       , dbms_lob.lob_readwrite',
'      );',
'',
'  -- Process the BLOB in chunks and convert to HEX',
'      WHILE l_offset <= l_blob_length LOOP',
'         l_amount    := least(',
'            l_chunk_size',
'          ,(l_blob_length - l_offset + 1)',
'         );',
'',
'    -- Extract the BLOB chunk to a RAW value',
'         l_raw_chunk := dbms_lob.substr(',
'            l_encrypted_blob',
'          , l_amount',
'          , l_offset',
'         );',
'',
'    -- Convert the RAW chunk to its hexadecimal representation',
'         l_hex_chunk := rawtohex(l_raw_chunk);',
'',
'    -- Append the hex chunk to the encrypted_hex CLOB',
'         dbms_lob.writeappend(',
'            l_encrypted_hex',
'          , length(l_hex_chunk)',
'          , l_hex_chunk',
'         );',
'',
'    -- Update the offset',
'         l_offset    := l_offset + l_amount;',
'      END LOOP;',
'',
'      dbms_lob.close(l_encrypted_hex);',
'      RETURN l_encrypted_hex;',
'   EXCEPTION',
'      WHEN OTHERS THEN',
'         dbms_output.put_line(''Error: '' || sqlerrm);',
'         RAISE;',
'   END encrypt_clob_aes;',
'',
'END "ARF_LITE_UTIL";',
'/ '))
);
end;
/
prompt --application/deployment/install/install_load_demo_data
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(221296156061503937)
,p_install_id=>wwv_flow_imp.id(218305616005660395)
,p_name=>'load-demo-data'
,p_sequence=>20
,p_script_type=>'INSTALL'
,p_condition_type=>'NOT_EXISTS'
,p_condition=>'select 1 from ARF_LITE_CONFIG'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'REM INSERTING into ARF_LITE_CONFIG',
'SET DEFINE OFF;',
'Insert into ARF_LITE_CONFIG (BASE_URL,API_KEY,ENCRYPTION_ENABLED,ENCRYPTION_KEY,ENCRYPTION_IV,CREATED_BY,CREATED_ON,UPDATED_BY,UPDATED_ON) values (''https://ociarfdemo.maathradev.com'',''key'',''N'',''A3F67C9D8E0B2451F68C3E91D6B7A2F549E80DCCB6F1E392A3D5C7F8'
||'421B6D3E'',''F1B27498D2E3A6C75089F4BA3D65C2E7'', null, null, null, null);',
'commit;',
'/',
'REM INSERTING into ARF_LITE_REPORT_DEFINITION',
'SET DEFINE OFF;',
'Insert into ARF_LITE_REPORT_DEFINITION (SHORT_CODE,REPORT_QUERY,DESCRIPTION,ACTIVE,CREATED_BY,CREATED_ON,UPDATED_BY,UPDATED_ON,OUTPUT_FORMAT,MAIN_REPORT_NAME,REPORT_PARAM) values (''ORDER_SLIP_QR'',TO_CLOB(q''[WITH count_base AS (',
'   SELECT',
'      level sticker_count',
'   FROM',
'      dual',
'   CONNECT BY',
'      level <= NVL($p{p_count}, 1)',
'),',
'inv_header_base AS (',
'   SELECT',
'      ord.order_id,',
'      TO_CHAR(TRUNC(ord.order_date), ''DD MON YYYY'') AS order_date,',
'      ord.order_mode,',
'      ocu.cust_first_name || '' '' || ocu.cust_last_name AS name,',
'      ocu.street_address,',
'      ocu.postal_code,',
'      ocu.city,',
'      ocu.state_province,',
'      con.country_name,',
'      ocu.phone_number,',
'      ocu]'')',
'|| TO_CLOB(q''[.cust_email,',
'      CASE ord.order_status',
'         WHEN 0  THEN ''Not Fully Entered''',
'         WHEN 1  THEN ''Entered''',
'         WHEN 2  THEN ''Canceled - bad credit''',
'         WHEN 3  THEN ''Canceled by Customer''',
'         WHEN 4  THEN ''Shipped - whole order''',
'         WHEN 5  THEN ''Shipped - replacement items''',
'         WHEN 6  THEN ''Shipped - backlog on items''',
'         WHEN 7  THEN ''Shipped - special delivery''',
